// Helpers for the images stored in  public/images/**
// `virtual:image-manifest` is generated by vite-plugin-image-manifest.js and
// lists the files that really exist, so we never render a broken image.
import manifest from 'virtual:image-manifest'

export const IMAGE_BASE = '/images'

const IMAGE_EXT = /\.(png|jpe?g|webp|gif|avif|svg)$/i
export const isImage = (file) => IMAGE_EXT.test(file)

/** "projects/kshopping/shot-01.png" -> "/images/projects/kshopping/shot-01.png" (URL-safe) */
export const toUrl = (relPath) => encodeURI(`${IMAGE_BASE}/${relPath}`)

/** "kshopping-01.png" -> "Kshopping 01" */
export const humanize = (text = '') =>
  text
    .replace(/\.[^.]+$/, '')
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .trim()

/** Does public/images/<relPath> exist? */
export function fileExists(relPath) {
  if (!relPath) return false
  const i = relPath.lastIndexOf('/')
  const dir = relPath.slice(0, i)
  const file = relPath.slice(i + 1)
  return Boolean(manifest[dir]?.includes(file))
}

/** URL for <relPath> if the file exists, otherwise null. */
export const assetUrl = (relPath) => (fileExists(relPath) ? toUrl(relPath) : null)

/**
 * All images inside a folder (optionally including sub-folders).
 * Returns [{ path, src, name, folder }] sorted by file name.
 */
export function listImages(folder, { recursive = false } = {}) {
  const folders = Object.keys(manifest).filter((key) =>
    recursive ? key === folder || key.startsWith(`${folder}/`) : key === folder
  )

  return folders.flatMap((dir) =>
    manifest[dir].filter(isImage).map((file) => ({
      path: `${dir}/${file}`,
      src: toUrl(`${dir}/${file}`),
      name: humanize(file),
      folder: dir,
    }))
  )
}
